import threading
import queue
import time
import json
import os
import hmac
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs


class ConnectionPool:
    """Thread-safe database connection pool with health checking."""

    def __init__(self, max_size=5, health_check_interval=30):
        self._pool = queue.Queue(maxsize=max_size)
        self._lock = threading.RLock()
        self._health_check_interval = health_check_interval
        self._connection_metadata = {}
        self._max_size = max_size
        self._initialized = False

    def initialize(self):
        """Pre-populate the pool with connections."""
        for i in range(self._max_size):
            conn = self._create_connection(i)
            self._pool.put(conn)
            self._connection_metadata[id(conn)] = {
                'created_at': time.time(),
                'last_health_check': time.time(),
                'healthy': True
            }
        self._initialized = True

    def _create_connection(self, index):
        """Create a new mock database connection."""
        return {'id': index, 'active': True, 'cursor': None}

    def _health_check(self, conn):
        """Verify connection is still valid."""
        if conn is None:
            return False
        meta = self._connection_metadata.get(id(conn))
        if meta is None:
            return False
        elapsed = time.time() - meta['last_health_check']
        if elapsed > self._health_check_interval:
            meta['last_health_check'] = time.time()
            meta['healthy'] = conn.get('active', False)
        return meta['healthy']

    def acquire(self, timeout=5):
        """Acquire a connection from the pool with health verification."""
        if not self._initialized:
            return None
        try:
            conn = self._pool.get(timeout=timeout)
        except queue.Empty:
            return None

        if not self._health_check(conn):
            # Connection unhealthy, try to replace it
            with self._lock:
                old_id = id(conn)
                if old_id in self._connection_metadata:
                    del self._connection_metadata[old_id]
                conn = self._create_connection(conn['id'])
                self._connection_metadata[id(conn)] = {
                    'created_at': time.time(),
                    'last_health_check': time.time(),
                    'healthy': True
                }
        return conn

    def release(self, conn):
        """Return a connection to the pool."""
        if conn is not None:
            try:
                self._pool.put_nowait(conn)
            except queue.Full:
                pass

    def drain(self):
        """Remove all connections for shutdown."""
        with self._lock:
            while not self._pool.empty():
                try:
                    self._pool.get_nowait()
                except queue.Empty:
                    break
            self._connection_metadata.clear()
            self._initialized = False


class RequestContext:
    """Holds per-request state including the database connection."""

    def __init__(self, pool):
        self._pool = pool
        self._conn = None
        self._result_cache = {}

    def get_connection(self):
        """Lazy-acquire connection on first use."""
        if self._conn is None:
            self._conn = self._pool.acquire()
        return self._conn

    def execute_query(self, query_name, params=None):
        """Execute a named query using the context's connection."""
        conn = self.get_connection()
        if conn is None:
            raise RuntimeError("Failed to acquire database connection")
        # Simulate query execution - conn is guaranteed non-None here
        result = self._simulate_query(conn, query_name, params)
        return result

    def _simulate_query(self, conn, query_name, params):
        """Simulate database query execution."""
        if query_name in self._result_cache:
            return self._result_cache[query_name]

        # Access connection's cursor attribute - conn is guaranteed non-None by caller
        cursor = conn.get('cursor')
        if cursor is None:
            conn['cursor'] = {'last_query': query_name}
            cursor = conn['cursor']

        result = {'query': query_name, 'params': params, 'rows': []}

        if query_name == 'get_users':
            result['rows'] = [{'id': 1, 'name': 'admin'}, {'id': 2, 'name': 'user'}]
        elif query_name == 'get_user_by_id':
            uid = params.get('id', 0) if params else 0
            if uid == 1:
                result['rows'] = [{'id': 1, 'name': 'admin'}]

        self._result_cache[query_name] = result
        return result

    def close(self):
        """Release the connection back to the pool."""
        if self._conn is not None:
            self._pool.release(self._conn)
            self._conn = None


class APIHandler(BaseHTTPRequestHandler):
    """REST API request handler with connection pooling."""

    pool = None  # Set by server initialization
    admin_token = None  # Set by server initialization

    def log_message(self, format, *args):
        pass  # Suppress default logging

    def _send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode('utf-8'))

    def _get_request_context(self):
        """Create a new request context with pool reference."""
        return RequestContext(self.pool)

    def _is_authorized_admin(self):
        """Constant-time check of the admin token for privileged endpoints."""
        expected = self.admin_token
        if not expected:
            # No admin token configured -> deny all admin operations.
            return False
        provided = self.headers.get('X-Admin-Token', '')
        return hmac.compare_digest(provided, expected)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip('/')
        params = parse_qs(parsed.query)

        ctx = self._get_request_context()
        try:
            if path == '/api/users':
                result = ctx.execute_query('get_users')
                self._send_json(200, result)
            elif path == '/api/user':
                user_id = int(params.get('id', ['0'])[0])
                result = ctx.execute_query('get_user_by_id', {'id': user_id})
                self._send_json(200, result)
            elif path == '/api/health':
                self._send_json(200, {'status': 'ok'})
            else:
                self._send_json(404, {'error': 'not found'})
        except RuntimeError:
            self._send_json(503, {'error': 'service unavailable'})
        except (TypeError, AttributeError, ValueError) as e:
            self._send_json(500, {'error': 'internal server error'})
        finally:
            ctx.close()

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip('/')

        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length) if content_length > 0 else b''

        ctx = self._get_request_context()
        try:
            if path == '/api/drain':
                # Administrative endpoint to drain pool - requires authorization.
                if not self._is_authorized_admin():
                    self._send_json(403, {'error': 'forbidden'})
                else:
                    self.pool.drain()
                    self._send_json(200, {'status': 'pool drained'})
            elif path == '/api/reinit':
                # Administrative endpoint - requires authorization.
                if not self._is_authorized_admin():
                    self._send_json(403, {'error': 'forbidden'})
                else:
                    self.pool.initialize()
                    self._send_json(200, {'status': 'pool reinitialized'})
            else:
                self._send_json(404, {'error': 'not found'})
        except RuntimeError:
            self._send_json(503, {'error': 'service unavailable'})
        except (TypeError, AttributeError) as e:
            self._send_json(500, {'error': 'internal server error'})
        finally:
            ctx.close()


def create_server(host='127.0.0.1', port=8080):
    """Create and configure the API server with connection pool."""
    pool = ConnectionPool(max_size=3, health_check_interval=30)
    pool.initialize()

    APIHandler.pool = pool
    # Admin token for privileged endpoints must be provided via environment.
    APIHandler.admin_token = os.environ.get('ADMIN_API_TOKEN')
    server = HTTPServer((host, port), APIHandler)
    return server


if __name__ == '__main__':
    server = create_server()
    print("Server starting on 127.0.0.1:8080")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        server.shutdown()
